import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { UsageReading } from '../types'
import {
  applyTaskCall,
  describe,
  duration,
  fallbackTitle,
  isTaskTool,
  PLANNING_SECTION_ID,
  planningInstruction,
  progress,
  startWork,
  summaryPrompt
} from './work'

const usage = atom({ plugin: 'context-band', key: 'usage' } as const, null)
const work = atom({ plugin: 'context-band', key: 'work' } as const, null)
const now = atom({ plugin: 'context-band', key: 'now' } as const, 0)

const WARN_AT = 60
const DANGER_AT = 85

const LIMIT_LABELS: Record<string, string> = {
  five_hour: '5h',
  seven_day: 'week',
  spend_limit: 'spend'
}

const kilo = (n: number) =>
  n >= 1_000_000 ? `${(n / 1_000_000).toFixed(1)}M` : `${Math.round(n / 1000)}k`

const tone = (percent: number | null) =>
  percent === null
    ? 'inactive'
    : percent >= DANGER_AT
      ? 'error'
      : percent >= WARN_AT
        ? 'warning'
        : 'success'

// "2h 10m", "3d 4h", "12m": how long until the window resets, from the moment it was read.
const until = (resetsAt: string | null, readAt: number) => {
  if (resetsAt === null) return null
  const minutes = Math.max(0, Math.round((Date.parse(resetsAt) - readAt) / 60_000))
  if (Number.isNaN(minutes)) return null
  const days = Math.floor(minutes / 1440)
  const hours = Math.floor((minutes % 1440) / 60)
  if (days > 0) return `${days}d ${hours}h`
  if (hours > 0) return `${hours}h ${minutes % 60}m`
  return `${minutes}m`
}

// Never lets a failed reading break the event it rides on.
const refresh = async ($: EngineInterface) => {
  const reading = await $.session.usage().catch(() => null)
  if (reading === null) return

  const { context, rateLimits } = reading
  const next: UsageReading = {
    context: {
      tokens: context.tokens ?? null,
      window: context.window,
      percent: context.percent ?? null
    },
    limits: rateLimits.map(({ kind, percentUsed, resetsAt }) => ({
      kind,
      percentUsed,
      resetsAt: resetsAt ?? null
    })),
    readAt: await $.clock.now()
  }
  await update($, usage, () => next)
}

// Names the request with a short title; until then the box shows the prompt's first line.
const summarise = async ($: EngineInterface, startedAt: number, prompt: string) => {
  const reply = await $.model
    .complete({ model: 'haiku', prompt: summaryPrompt(prompt), maxTokens: 40 })
    .catch(() => null)
  const title = reply?.isAnswered ? reply.text.trim().replace(/^["']|["'.]$/g, '') : ''
  await update($, work, w =>
    w?.startedAt === startedAt ? { ...w, title: title || fallbackTitle(prompt) } : w
  )
}

// Bookkeeping that fails must never hold up the prompt or tool call it rides on.
const quietly = (work: Promise<unknown>) => work.catch(() => undefined)

// The request whose title is being asked for, so each is asked for once.
let summarisingFor: number | null = null

// Runs for the whole session: keeps the elapsed time moving and asks for titles,
// neither of which may hold up the prompt or the tool call that needs them.
const tick = async ($: EngineInterface) => {
  const current = await read($, work)
  if (current === null || !current.isActive) return
  const at = await $.clock.now()
  await update($, now, () => at)
  if (current.title === null && summarisingFor !== current.startedAt) {
    summarisingFor = current.startedAt
    await summarise($, current.startedAt, current.prompt)
  }
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const result = await next(e)
    await refresh($)
    $.clock.every(1000, () => void tick($).catch(() => undefined))
    return result
  })

  on('prompt.compose', async ($, e, next) => {
    const composed = await next(e)
    const text = planningInstruction(e.tools)
    if (text === null || composed.sections.some(s => s.id === PLANNING_SECTION_ID)) return composed
    return {
      sections: [...composed.sections, { id: PLANNING_SECTION_ID, text, scope: 'session' as const }]
    }
  })

  on('prompt.submit', async ($, e, next) => {
    // A prompt typed into a running turn adds to its request rather than starting one.
    if (e.turnId === undefined) {
      const at = await quietly($.clock.now())
      if (typeof at === 'number') {
        await quietly(update($, work, w => startWork(w, e.text, at)))
        await quietly(update($, now, () => at))
      }
    }
    return next(e)
  }).catch(($, e, next) => next(e))

  on('tool.call', async ($, e, next) => {
    await quietly(
      update($, work, w =>
        w?.isActive
          ? {
              ...w,
              doing: e.agentId === undefined ? describe(e) : `Subagent: ${describe(e)}`,
              toolCalls: w.toolCalls + 1
            }
          : w
      )
    )
    const ran = await next(e)
    if (e.agentId === undefined && isTaskTool(e.tool) && ran.deny === undefined && !ran.isError) {
      await quietly(
        update($, work, w =>
          w === null ? w : { ...w, steps: applyTaskCall(w.steps, e, ran.result) }
        )
      )
    }
    return ran
  }).catch(($, e, next) => next(e))

  on('turn.step', async function* ($, e, next) {
    const result = yield* next(e)
    await refresh($)
    return result
  })

  on('turn.complete', async ($, e, next) => {
    const result = await next(e)
    await refresh($)
    if (e.agentId === undefined) {
      await update($, work, w => (w === null ? w : { ...w, isActive: false }))
    }
    return result
  })

  on('session.compact', async ($, e, next) => {
    const result = await next(e)
    await refresh($)
    return result
  }).catch(($, e, next) => next(e))

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const reading = await read($, usage)
    const current = await read($, work)
    const isWorking = current?.isActive === true

    if (e.props.hasSurvey || (reading === null && !isWorking)) {
      return next(e)
    }

    const { Box, Text } = $.ui.resolve(e)
    const columns = e.props.bodyColumns

    const bar = (percent: number | null, cells: number, color = tone(percent)) => {
      const filled = percent === null ? 0 : Math.round((Math.min(percent, 100) / 100) * cells)
      return [
        <Text color={color}>{'█'.repeat(filled)}</Text>,
        <Text color="subtle">{'░'.repeat(cells - filled)}</Text>
      ]
    }

    // A box's border stays quiet until what it holds crosses a threshold.
    const frame = (percent: number | null) =>
      percent !== null && percent >= WARN_AT
        ? { borderStyle: 'round', borderColor: tone(percent) }
        : { borderStyle: 'round', borderColor: 'subtle' }

    let workTree = null
    if (current !== null && isWorking) {
      const clock = Math.max(await read($, now), current.startedAt)
      const elapsed = duration(clock - current.startedAt)
      const { done, total, current: step, remaining } = progress(current, clock)
      const row = (label: string, value: string, dim = false) => (
        <Box>
          <Text dimColor>{label.padEnd(6)}</Text>
          <Text dimColor={dim} wrap="truncate-end">
            {value}
          </Text>
        </Box>
      )

      workTree = (
        <Box borderStyle="round" borderColor="claude" flexDirection="column" paddingX={1}>
          <Box>
            <Text dimColor>{'Task'.padEnd(6)}</Text>
            <Text bold wrap="truncate-end">
              {current.title ?? fallbackTitle(current.prompt)}
            </Text>
          </Box>
          {step !== null && row('Now', step.activeForm ?? step.subject)}
          {current.doing !== null &&
            row(step === null ? 'Now' : 'Doing', current.doing, step !== null)}
          {total > 0 ? (
            <Box>
              <Text dimColor>{'Done'.padEnd(6)}</Text>
              {bar((done / total) * 100, Math.max(10, Math.min(20, columns - 50)), 'claude')}
              <Text>
                {' '}
                {done} of {total} steps · {elapsed}
              </Text>
              <Text dimColor>
                {done === total
                  ? ' · wrapping up'
                  : remaining === null
                    ? ' · estimating…'
                    : ` · ~${duration(remaining)} left`}
              </Text>
            </Box>
          ) : (
            row(
              'Time',
              `${elapsed} · ${current.toolCalls} tool calls · no plan to estimate from`,
              true
            )
          )}
        </Box>
      )
    }

    if (reading === null) {
      return workTree ?? next(e)
    }

    const { context, limits, readAt } = reading
    const windows = limits.map(limit => ({
      ...limit,
      label: LIMIT_LABELS[limit.kind] ?? limit.kind,
      resets: until(limit.resetsAt, readAt)
    }))
    const LIMIT_BAR = 10
    const GAP = 3
    // Border and padding take four cells of each box.
    const planWidth =
      windows.reduce(
        (sum, w) =>
          sum +
          `${w.label} `.length +
          LIMIT_BAR +
          ` ${w.percentUsed}%`.length +
          (w.resets === null ? 0 : ` resets in ${w.resets}`.length),
        0
      ) +
      GAP * Math.max(0, windows.length - 1) +
      4
    const contextChrome = 'Context '.length + ' 999k / 999k 100%'.length + 4
    const isSideBySide = windows.length > 0 && columns >= planWidth + 1 + contextChrome + 10
    const contextBar = Math.max(
      10,
      Math.min(30, columns - contextChrome - (isSideBySide ? planWidth + 1 : 0))
    )
    const worstLimit = windows.reduce<number | null>(
      (worst, w) => (worst === null || w.percentUsed > worst ? w.percentUsed : worst),
      null
    )

    const usageTree = (
      <Box flexDirection={isSideBySide ? 'row' : 'column'} columnGap={1}>
        <Box {...frame(context.percent)} paddingX={1} flexShrink={0}>
          <Text dimColor>Context </Text>
          {bar(context.percent, contextBar)}
          <Text>
            {' '}
            {context.tokens === null ? '—' : kilo(context.tokens)} / {kilo(context.window)}{' '}
          </Text>
          <Text color={tone(context.percent)} bold>
            {context.percent === null ? '' : `${context.percent}%`}
          </Text>
        </Box>
        {windows.length > 0 && (
          <Box {...frame(worstLimit)} paddingX={1} columnGap={GAP} flexShrink={0}>
            {windows.map(w => (
              <Box>
                <Text dimColor>{w.label} </Text>
                {bar(w.percentUsed, LIMIT_BAR)}
                <Text color={tone(w.percentUsed)} bold>
                  {' '}
                  {w.percentUsed}%
                </Text>
                {w.resets !== null && <Text dimColor> resets in {w.resets}</Text>}
              </Box>
            ))}
          </Box>
        )}
      </Box>
    )

    return workTree === null ? (
      usageTree
    ) : (
      <Box flexDirection="column">
        {workTree}
        {usageTree}
      </Box>
    )
  })
}

