import type { ToolCallInput } from 'claude-code'

import type { Step, Work } from '../types'

const basename = (path: string) => path.split('/').pop() ?? path

const clip = (text: string, length: number) =>
  text.length > length ? `${text.slice(0, length - 1)}…` : text

/** What a tool call is doing, as a person would say it. */
export const describe = (e: ToolCallInput): string => {
  switch (e.tool) {
    case 'Bash':
      return e.description ? clip(e.description, 80) : `Running ${clip(e.command, 60)}`
    case 'Read':
      return `Reading ${basename(e.file_path)}`
    case 'Edit':
      return `Editing ${basename(e.file_path)}`
    case 'Write':
      return `Writing ${basename(e.file_path)}`
    case 'NotebookEdit':
      return `Editing ${basename(e.notebook_path)}`
    case 'Agent':
      return `Delegating: ${clip(e.description, 60)}`
    case 'Skill':
      return `Loading the ${e.skill} skill`
    case 'WebSearch':
      return `Searching the web for ${clip(e.query, 50)}`
    case 'WebFetch':
      return `Fetching ${clip(e.url, 60)}`
    case 'ToolSearch':
      return 'Looking up tools'
    case 'AskUserQuestion':
      return 'Waiting for your answer'
    case 'TaskCreate':
    case 'TaskUpdate':
    case 'TodoWrite':
      return 'Planning'
    default:
      return e.tool.startsWith('mcp__') ? `Using ${e.tool.split('__').slice(1).join(' ')}` : e.tool
  }
}

/** A prompt short enough to be its own title needs no summary. */
export const fallbackTitle = (prompt: string) => {
  const firstLine = prompt.trim().split('\n')[0] ?? ''
  return clip(firstLine, 80)
}

export const needsSummary = (prompt: string) => prompt.trim().length > 60 || prompt.includes('\n')

export const summaryPrompt = (prompt: string) =>
  [
    'Write a title of at most 8 words for this request to a coding assistant.',
    "Write it in the request's own language. Reply with the title only: no quotes, no full stop.",
    '',
    '<request>',
    prompt.slice(0, 4000),
    '</request>'
  ].join('\n')

export const startWork = (previous: Work | null, prompt: string, now: number): Work => {
  // A task list left unfinished carries over: the new request most likely continues it.
  const steps = previous?.steps.some(s => s.status !== 'completed') ? previous.steps : []
  return {
    prompt,
    title: needsSummary(prompt) ? null : fallbackTitle(prompt),
    startedAt: now,
    isActive: true,
    steps,
    doneAtStart: steps.filter(s => s.status === 'completed').length,
    doing: null,
    toolCalls: 0
  }
}

type TaskResult = { task?: { id?: string } }

/** Folds a finished task-list tool call into the steps. */
export const applyTaskCall = (steps: Step[], e: ToolCallInput, result: unknown): Step[] => {
  switch (e.tool) {
    case 'TaskCreate': {
      const id = (result as TaskResult | undefined)?.task?.id
      if (id === undefined) return steps
      return [
        ...steps,
        { id, subject: e.subject, activeForm: e.activeForm ?? null, status: 'pending' }
      ]
    }
    case 'TaskUpdate': {
      if (e.status === 'deleted') return steps.filter(s => s.id !== e.taskId)
      const status = e.status
      return steps.map(s =>
        s.id === e.taskId
          ? {
              ...s,
              subject: e.subject ?? s.subject,
              activeForm: e.activeForm ?? s.activeForm,
              status: status ?? s.status
            }
          : s
      )
    }
    case 'TodoWrite':
      return e.todos.map((todo, i) => ({
        id: `todo-${i}`,
        subject: todo.content,
        activeForm: todo.activeForm,
        status: todo.status
      }))
    default:
      return steps
  }
}

export const isTaskTool = (tool: string) =>
  tool === 'TaskCreate' || tool === 'TaskUpdate' || tool === 'TodoWrite'

/** "45s", "2m 10s", "1h 5m". */
export const duration = (ms: number) => {
  const seconds = Math.max(0, Math.round(ms / 1000))
  const h = Math.floor(seconds / 3600)
  const m = Math.floor((seconds % 3600) / 60)
  if (h > 0) return `${h}h ${m}m`
  if (m > 0) return `${m}m ${seconds % 60}s`
  return `${seconds}s`
}

export type Progress = {
  done: number
  total: number
  current: Step | null
  /** Milliseconds left at the pace so far; null until a step of this request is done. */
  remaining: number | null
}

export const progress = (work: Work, now: number): Progress => {
  const total = work.steps.length
  const done = work.steps.filter(s => s.status === 'completed').length
  const current = work.steps.find(s => s.status === 'in_progress') ?? null
  const doneHere = done - work.doneAtStart
  const remaining =
    doneHere > 0 && total > done ? ((now - work.startedAt) / doneHere) * (total - done) : null
  return { done, total, current, remaining }
}

export const PLANNING_SECTION_ID = 'context-band:plan-with-tasks'

/** The system prompt's instruction to plan with the task list, for whichever task tool the session has. */
export const planningInstruction = (tools: readonly string[]) => {
  const tool = tools.includes('TaskCreate')
    ? 'TaskCreate and TaskUpdate'
    : tools.includes('TodoWrite')
      ? 'TodoWrite'
      : null
  if (tool === null) return null
  return [
    '# Planning with the task list',
    `When a request takes more than two steps, break it into tasks with ${tool} before starting the work, each with a short activeForm.`,
    'Mark each task in_progress as you start it and completed as soon as it is done, one at a time.',
    'The person watches these tasks to see what is being worked on and how long is left, so keep them current.',
    'Skip the task list for questions and for requests that take one or two steps.'
  ].join('\n')
}

