export type ContextFill = { tokens: number | null; window: number; percent: number | null }

export type LimitWindow = { kind: string; percentUsed: number; resetsAt: string | null }

export type UsageReading = { context: ContextFill; limits: LimitWindow[]; readAt: number }

export type StepStatus = 'pending' | 'in_progress' | 'completed'

/** One entry of the model's task list (TaskCreate/TaskUpdate or TodoWrite). */
export type Step = { id: string; subject: string; activeForm: string | null; status: StepStatus }

/** The request being worked on, from the prompt that started it until the turn ends. */
export type Work = {
  prompt: string
  /** A short title for the request; null until the summary has come back. */
  title: string | null
  startedAt: number
  isActive: boolean
  steps: Step[]
  /** Steps already completed when this request started, so the estimate counts only its own. */
  doneAtStart: number
  /** The latest tool call, described for a person. */
  doing: string | null
  toolCalls: number
}

declare module 'claude-code' {
  interface PluginState {
    'context-band': { usage: UsageReading | null; work: Work | null; now: number }
  }
}
